import re, shutil
shutil.copy('init.xlsx','output.xlsx')
from openpyxl import load_workbook

wb = load_workbook('output.xlsx')
ws = wb['Sheet1']

# find rows in column A matching 400-...-A
def is_marker(val):
    return isinstance(val,str) and re.match(r'^400-.+-A$', val) is not None
def is_400(val):
    return isinstance(val,str) and val.startswith('400-')

rows_A = [r for r in range(1, ws.max_row+1) if ws.cell(r,1).value not in (None,'')]
print(rows_A)

# find the -A row
start = None
for r in rows_A:
    if is_marker(ws.cell(r,1).value):
        start = r
        break
if start is None:
    print("no -A row, nothing to delete")
else:
    # next 400- row after start
    nxt = None
    for r in rows_A:
        if r>start and is_400(ws.cell(r,1).value):
            nxt = r
            break
    if nxt is None:
        end = ws.max_row
    else:
        end = nxt-1
    print("delete rows", start, "to", end)
    # delete rows upwards
    for r in range(end, start-1, -1):
        ws.delete_rows(r, 1)
wb.save('output.xlsx')
EOF
